 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Find rectangular, fully framed colored objects. Their interior can be
    # either an encoded pattern or an empty frame.
    boxes = []
    colors = {v for row in g for v in row if v != 0}
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if g[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        if not all(g[r0][c] == color and g[r1][c] == color for c in range(c0,c1+1)):
            continue
        if not all(g[r][c0] == color and g[r][c1] == color for r in range(r0,r1+1)):
            continue
        # Make sure this color has no cells beyond the rectangular boundary
        # or in other disconnected objects.
        if any(r0 < r < r1 and c0 < c < c1 for r,c in cells):
            # Interior pattern is expected to be the same color.
            pass
        boxes.append((color,r0,r1,c0,c1))
    donors = []
    for color,r0,r1,c0,c1 in boxes:
        pat = [[1 if g[r][c] == color else 0 for c in range(c0+1,c1)] for r in range(r0+1,r1)]
        if any(any(row) for row in pat):
            donors.append((color,r0,r1,c0,c1,pat))
    if not donors:
        return g
    # The encoded pattern object is the one with the largest nonempty interior;
    # other nonempty framed objects are preserved as independent exemplars.
    color,r0,r1,c0,c1,pat = max(donors, key=lambda d: (len(d[5])*len(d[5][0]), sum(map(sum,d[5]))))
    ph,pw = len(pat),len(pat[0])
    for col,a,b,x,y in boxes:
        if col == color:
            continue
        ih,iw = b-a-1,y-x-1
        interior = [(r,c) for r in range(a+1,b) for c in range(x+1,y) if g[r][c] == col]
        if interior:
            continue
        # Blank frames that can host the rule are filled from the pattern's
        # upper-left; undersized frames are removed.
        if ih >= 3 and iw >= pw:
            for r in range(ih):
                for c in range(iw):
                    g[a+1+r][x+1+c] = col if r < ph and c < pw and pat[r][c] else 0
        else:
            for r in range(a,b+1):
                for c in range(x,y+1):
                    g[r][c] = 0
    return g

if __name__ == '__main__':
    pass
