        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        if not (all(g[r0][c] == color and g[r1][c] == color for c in range(c0, c1+1)) and
                all(g[r][c0] == color and g[r][c1] == color for r in range(r0, r1+1))):
            continue
        pattern = [[1 if g[r][c] == color else 0
                    for c in range(c0+1, c1)] for r in range(r0+1, r1)]
