    dc, dr0, dr1, dc0, dc1, mask = donor
    mh, mw = len(mask), len(mask[0])
    for color, r0, r1, c0, c1, _ in boxes:
        if (color, r0, r1, c0, c1) == (dc, dr0, dr1, dc0, dc1):
            continue
        ih, iw = r1-r0-1, c1-c0-1
        # Matching frames (and the one-row-short variant) receive the stencil;
        # unrelated-sized frames are removed.
        compatible = (iw == mw and ih in (mh, mh-1))
        if compatible:
