 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Frames are same-color hollow rectangles. The pattern donor is the
    # frame with the densest non-background interior.
    frames = []
    for color in range(1, 10):
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not pts:
            continue
        r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
        c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        if (all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0,c1+1)) and
            all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0,r1+1))):
            mask = [[grid[r][c] == color for c in range(c0+1,c1)] for r in range(r0+1,r1)]
            frames.append((color,r0,r1,c0,c1,mask))
    if not frames:
        return out
    source = max(frames, key=lambda f: sum(map(sum,f[5])))
    color,r0,r1,c0,c1,mask = source
    # Overlay source interior pattern at corresponding positions in every
    # framed region; preserve the frame itself and don't rescale.
    for tc,a,b,x,y,_ in frames:
        if (tc,a,b,x,y)==(color,r0,r1,c0,c1):
            continue
        for i,row in enumerate(mask):
            for j,on in enumerate(row):
                if a+1+i < b and x+1+j < y:
                    out[a+1+i][x+1+j] = tc if on else 0
    return out

